15	/** Bounded slider with explicit default/custom state for optional diagram formatting. */
16	export function OptionalSliderField(props: OptionalSliderFieldProps) {
17	    const { helperText, initialCustomValue, label, maximum, minimum, onChange, unit, value } = props;
18	    const labelId = useId();
19	    const [customValue, setCustomValue] = useState(value ?? initialCustomValue);
20	    const displayedValue = value ?? customValue;
21	    const handleChange = (_event: Event, nextValue: number | number[]) => {
22	        if (Array.isArray(nextValue)) throw new Error(`${label} requires one slider value`);
23	        setCustomValue(nextValue);
24	        onChange(nextValue);
25	    };
26	    const handleUseCustom = () => onChange(customValue);
27	    const handleUseDefault = () => onChange(undefined);
28	
29	    return (
30	        <Stack spacing={0.5}>
31	            <Stack direction="row" spacing={1} sx={{ alignItems: 'center', justifyContent: 'space-between' }}>
32	                <Typography color="text.secondary" id={labelId} variant="caption">{label}</Typography>
33	                <Typography aria-label={`${label} value`} variant="body2">
34	                    {value === undefined ? 'Default' : `${value} ${unit}`}
35	                </Typography>
36	            </Stack>
37	            <Slider
38	                aria-labelledby={labelId}
39	                disabled={value === undefined}
40	                max={maximum}
41	                min={minimum}
42	                onChange={handleChange}
43	                value={displayedValue}
44	                valueLabelDisplay="auto"
45	            />
46	            <Button
