import FormatColorResetOutlined from '@mui/icons-material/FormatColorResetOutlined'
import { Box, ButtonBase, Popover, Tooltip, Typography } from '@mui/material'
import { useState, type MouseEvent } from 'react'
import { ColorPickerField } from './color_picker_field'

const BUTTON_HEIGHT = 40
const DEFAULT_ICON_SIZE = 18
const PICKER_WIDTH = 260

interface ColorPickerButtonProps {
    label: string
    onChange: (value: string | undefined) => void
    /** `undefined` means the default colour is selected. */
    value: string | undefined
}

/** Compact colour control: a box showing the current colour that opens the colour picker, including a Default box. */
export function ColorPickerButton(props: ColorPickerButtonProps) {
    const { label, onChange, value } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const isDefault = value === undefined

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }

    const handleClose = () => {
        setAnchorElement(null)
    }

    return (
        <>
            <Tooltip title={`${label}: ${value ?? 'Default'}`}>
                <ButtonBase
                    aria-label={label}
                    onClick={handleOpen}
                    sx={{
                        bgcolor: value,
                        border: 1,
                        borderColor: 'custom.borderStrong',
                        borderRadius: 1,
                        color: 'text.secondary',
                        gap: 1,
                        height: BUTTON_HEIGHT,
                        width: '100%',
                    }}
                >
                    {isDefault ? (
                        <>
                            <FormatColorResetOutlined sx={{ fontSize: DEFAULT_ICON_SIZE }} />
                            <Typography variant="body2">Default</Typography>
                        </>
                    ) : null}
                </ButtonBase>
            </Tooltip>
            <Popover anchorEl={anchorElement} onClose={handleClose} open={!!anchorElement}>
                <Box sx={{ p: 1, width: PICKER_WIDTH }}>
                    <ColorPickerField label={label} onChange={onChange} showDefault value={value} />
                </Box>
            </Popover>
        </>
    )
}

/**
 * Theme configuration model: the user-editable color scheme and markdown styles
 * that feed the global theme service. Kept as plain data so it can be persisted
 * and read outside of React (see theme service and Electron main process).
 */

/** Semantic color roles the app exposes for configuration. */
export type ColorRole = 'primary' | 'secondary'

/** A single color role with its light/regular/dark variants. */
export interface ColorRoleVariants {
    light: string
    regular: string
    dark: string
}

/** The full editable color scheme: one set of variants per role. */
export type ColorSchemeConfig = Record<ColorRole, ColorRoleVariants>

/** Markdown elements that can be styled independently. */
export type MarkdownSection =
    | 'title1'
    | 'title2'
    | 'title3'
    | 'body'
    | 'caption'
    | 'link'
    | 'list'
    | 'blockquote'
    | 'inlineCode'
    | 'codeBlock'
    | 'table'

/** Font formatting flags for a markdown section. */
export interface MarkdownSectionFormatting {
    bold: boolean
    italic: boolean
    underline: boolean
}

/** Style applied to one markdown section. */
export interface MarkdownSectionStyle {
    color: string
